from pathlib import Path

TODAY = '2026-06-18'

S = {
    'fund': '[医疗保障基金使用监督管理条例](https://www.gov.cn/gongbao/content/2021/content_5591403.htm)',
    'retail': '[零售药店医疗保障定点管理暂行办法](https://www.gov.cn/zhengce/zhengceku/2021-01/12/content_5579286.htm)',
    'netsale': '[药品网络销售监督管理办法](https://www.gov.cn/gongbao/content/2022/content_5717002.htm)',
    'internet': '[互联网诊疗管理办法（试行）](https://www.gov.cn/gongbao/content/2019/content_5358684.htm)',
    'trace': '[国家药监局关于药品信息化追溯体系建设的指导意见](https://www.gov.cn/zhengce/zhengceku/2018-12/31/content_5434073.htm)',
    'anti': '[网络反不正当竞争暂行规定](https://www.gov.cn/zhengce/zhengceku/202405/content_6951056.htm)',
    'beijing': '[北京市医保局关于开展“互联网+”医保服务的通知](https://ybj.beijing.gov.cn/zwgk/2024zcwj/202406/t20240614_3712273.html)',
    'shanghai': '[上海医保移动支付/互联网购药医保在线支付试点信息](https://ybj.sh.gov.cn/ybdt/20240801/e36427537c9444d7a33be20808c51922.html)',
    'guangdong': '[广东省医保局网上买药刷医保操作说明](https://hsa.gd.gov.cn/zwdt/ywsd/content/post_4617055.html)',
    'zhejiang': '[浙江省医保定点零售药店“浙里云药房”互联网医保结算实施指南](https://ybj.zj.gov.cn/art/2025/11/19/art_1229225623_2579319.html)',
    'nhsa': '[国家医保局官网](https://www.nhsa.gov.cn/)',
    'catalog': '[2025年国家医保药品目录与商业健康保险创新药品目录通知](https://www.gov.cn/zhengce/zhengceku/202512/content_7050533.htm)',
}

def write(path, text):
    Path(path).write_text(text.strip() + '\n', encoding='utf-8')

def header(title, level='✅可正式引用'):
    return f'''# {title}\n\n> - 引用级别：{level}\n> - 最后更新：{TODAY}\n\n'''

def source_list(keys):
    return '\n'.join(f'- {S[k]}' for k in keys)

# 1 指标表
write('01-即时零售平台/补充资料/平台竞争指标表_流量供给履约医保处方药师.md', header('平台竞争指标表_流量供给履约医保处方药师', '✅可供研判参考') + f'''## 一句话定位\n\n本文回答：比较京东、美团、阿里等平台的医药即时零售能力时，应该看哪些指标。核心判断是：平台竞争指标表应至少包括**流量入口、供给能力、履约能力、医保支付、处方承接、药师服务**六类指标；这些指标用于定义比较维度和补证方向，不能直接得出“哪家平台领先”的结论。\n\n## 一、事实底座：平台竞争指标表\n\n| 指标大类 | 指标定义 | 可观察信息 | 适用场景 | 不能证明什么 |\n|---|---|---|---|---|\n| 流量入口 | 平台把用户导入买药场景的能力 | App入口、搜索承接、频道曝光、活动资源、医保专区 | 判断用户触达与下单入口 | 不能证明买药GMV、复购或盈利 |\n| 供给能力 | 平台可连接的药品和药店供给 | 合作药店、SKU、库存同步、DTP/OTC结构、夜间药店 | 判断附近是否有货 | 不能证明库存真实可得或药店利润改善 |\n| 履约能力 | 从下单到交付的稳定性 | 配送时效、缺货率、取消率、夜间履约、冷链/特殊药品边界 | 判断急用药和即时服务体验 | 不能证明药品质量管理合规 |\n| 医保支付 | 在线或到店医保结算能力 | 医保城市、医保专区、个人账户支付、门诊统筹、结算链路 | 判断医保购药便利性 | 不能证明全国通用或所有药品可报销 |\n| 处方承接 | 处方药从开方、审方到购药的闭环 | 处方来源、互联网复诊、审方时效、处方留痕、处方药占比 | 判断处方药和慢病场景 | 不能证明处方来源真实可靠，需回到具体链路核验 |\n| 药师服务 | 购药前后专业服务能力 | 在线药师、审方、用药咨询、售后、慢病随访 | 判断医药专业服务质量 | 不能证明每笔订单都有足够药学服务 |\n\n## 二、核心问题拆解\n\n### 1. 平台之间到底比什么？\n\n- **事实：** 普通即时零售常看流量、供给和履约；医药即时零售还必须加入医保、处方和药师指标。\n- **分析：** 平台买药竞争不是单纯补贴或配送速度竞争，而是“入口 + 药店供给 + 医保/处方/药师服务”的复合能力竞争。\n- **边界：** 平台财报或公开新闻通常不单独披露买药GMV、药品订单量和处方药占比。\n\n### 2. 哪些指标是医药场景独有？\n\n- **事实：** {S['netsale']}要求资质、处方来源、审方、平台责任、交易留痕和配送质量管理。\n- **分析：** 处方、医保、药师、追溯和质量管理是医药区别于普通即时零售的关键变量。\n- **边界：** 没有公开披露的细分指标只能写成“待核验能力”，不能写成已验证事实。\n\n### 3. 哪些指标需要后续补证？\n\n- **事实：** 公开资料常能看到入口、活动、平台合作和部分城市医保案例。\n- **分析：** 真正决定业务质量的是订单、复购、履约、毛利、处方审方和药师服务质量。\n- **边界：** 指标表是比较框架，不是排名表。\n\n## 三、对即时零售医药的影响\n\n- **对平台：** 竞争口径应从“补贴和流量”升级为“流量、供给、履约、医保、处方、药师”的六维比较。\n- **对药店：** 平台接入价值要看库存同步、履约稳定、医保定点、处方审方和药师工时。\n- **对药企：** OTC/消费健康更看流量和库存，处方药/慢病/DTP更看处方、医保和患者服务。\n- **对用户：** 可见入口和配送速度只是体验起点，医保支付、处方合规和售后服务决定安全边界。\n\n## 四、使用边界\n\n- 本文只定义指标，不评价平台排名。\n- 指标可用于访谈、资料采集和后续打分，但每项都需要公开披露、合同资料或实测数据支撑。\n- 若缺少买药GMV、药品订单、处方药占比、医保订单、药师响应和投诉售后数据，只能形成能力线索，不能形成确定结论。\n\n## 五、公开来源\n\n{source_list(['netsale','fund','retail','internet'])}\n''')

# 2 平台合规边界
write('01-即时零售平台/补充资料/平台医药合规边界_处方医保履约.md', header('平台医药合规边界_处方医保履约', '✅可供研判参考') + f'''## 一句话定位\n\n本文回答：平台做医药即时零售时，处方、医保和履约分别有哪些合规边界。核心判断是：平台不能把买药简单理解为“流量入口 + 配送”，而要同时满足药品网络销售、处方来源与审方、医保基金使用、定点药店协议、交易留痕和配送质量管理要求。\n\n## 一、事实底座：三类合规边界\n\n| 边界 | 核心要求 | 适用对象 | 可观察证据 | 不能证明什么 |\n|---|---|---|---|---|\n| 处方边界 | 处方来源真实可靠、实名制、处方审核调配、避免重复使用 | 平台、互联网医院、药店、药师 | 处方来源、审方记录、处方留痕、复诊规则 | 不能由买药入口推导处方链路合规 |\n| 医保边界 | 医保基金支付范围、实名购药、定点协议、费用结算和基金监管 | 医保部门、定点药店、平台、用户 | 定点资格、医保结算、个人账户/统筹口径、结算记录 | 不能由“医保专区”推导所有药品可医保支付 |\n| 履约边界 | 药品质量、储存配送、追溯、交易记录、投诉和不良反应处理 | 药店、平台、配送方、药企 | 配送协议、温控/包装、追溯码、售后记录 | 不能由配送速度证明药品质量合规 |\n\n## 二、核心问题拆解\n\n### 1. 平台能否直接销售处方药？\n\n- **事实：** {S['netsale']}要求处方药网络销售确保处方来源真实可靠，并进行处方审核调配。\n- **分析：** 平台可以提供交易和信息服务，但处方来源、审方责任和药店调配不能被流量入口替代。\n- **边界：** 看到处方药页面或买药入口，不等于处方链路合规。\n\n### 2. 线上医保支付能否全国复制？\n\n- **事实：** 医保支付受基金支付范围、地方政策、定点协议和信息系统接口约束。\n- **分析：** 北京、上海、广东、浙江等地已有不同模式，但城市范围、药品范围、支付账户和平台准入条件并不完全相同。\n- **边界：** 单个城市样本不能外推全国，也不能外推所有平台。\n\n### 3. 履约快是否等于合规强？\n\n- **事实：** 药品网络销售要求配送质量管理、交易记录留存和风险处理。\n- **分析：** 药品配送要看包装、储存、交接、追溯、售后和异常处理，不只是送达速度。\n- **边界：** 普通即时配送能力不能直接证明药品履约合规。\n\n## 三、对即时零售医药的影响\n\n- **对平台：** 需建立入驻审核、处方审核、药品信息展示、交易留痕、医保结算和投诉处理机制。\n- **对药店：** 需同时满足经营资质、医保定点、处方审核、药品储配和药师服务要求。\n- **对药企：** 处方药、DTP、冷链和特殊药品不能按普通快消品逻辑进入即时零售。\n- **对用户：** 线上购药便利性要服从实名、处方、医保支付范围和药品安全。\n\n## 四、使用边界\n\n- 本文定义合规边界，不证明任何平台已经完全满足要求。\n- 平台合规能力需要逐项核验备案、资质、协议、处方、医保结算和履约记录。\n- 合规边界只能说明“必须满足什么”，不能说明“业务规模有多大”。\n\n## 五、公开来源\n\n{source_list(['netsale','fund','retail','internet'])}\n''')

# 3 连锁药店医保能力对比
write('02-连锁药店/补充资料/连锁药店医保能力对比.md', header('连锁药店医保能力对比', '✅可供研判参考') + f'''## 一句话定位\n\n本文回答：比较连锁药店医保能力时应该看哪些项目。核心判断是：连锁药店医保能力不是“是否有医保定点”一个指标，而应拆成**定点资格、医保结算、门诊统筹/慢特病、处方承接、线上医保、基金合规和数据留痕**七类能力。\n\n## 一、事实底座：医保能力对比表\n\n| 能力项 | 定义 | 可观察证据 | 对即时零售的意义 | 不能证明什么 |\n|---|---|---|---|---|\n| 医保定点资格 | 药店是否与经办机构签订医保服务协议 | 定点名单、服务协议、门店公示 | 决定能否进入医保购药场景 | 不能证明线上医保可用 |\n| 医保结算能力 | 是否能完成医保个人账户或统筹结算 | 结算接口、医保电子凭证、票据和费用明细 | 决定支付便利性 | 不能证明所有药品可报销 |\n| 门诊统筹/慢特病 | 是否承接统筹或慢特病购药 | 地方政策、病种范围、处方资料 | 决定慢病复购价值 | 不能外推全部城市 |\n| 处方承接 | 是否能接收和审核处方 | 处方来源、审方记录、药师配置 | 决定处方药服务能力 | 不能证明处方来源可靠，需链路核验 |\n| 线上医保 | 是否支持线上医保购药 | 城市试点、平台专区、医保支付标识 | 决定O2O医保购药可能性 | 不能证明全国复制 |\n| 基金合规 | 是否有基金内控、培训和风控 | 内控制度、检查记录、处罚记录 | 决定合作风险 | 不能证明完全无违规风险 |\n| 数据留痕 | 是否保存处方、交易、配送和医保数据 | 系统记录、追溯码、销售凭证 | 决定可审计性 | 不能证明用户体验好 |\n\n## 二、核心问题拆解\n\n### 1. 医保能力为什么不能只看定点资格？\n\n- **事实：** {S['retail']}规范零售药店医保定点管理，{S['fund']}强调基金安全和定点医药机构责任。\n- **分析：** 定点资格是入口，实际服务还要看结算、处方、统筹、慢病和数据留痕。\n- **边界：** 定点药店不等于具备线上医保或门诊统筹能力。\n\n### 2. 哪些医保能力最影响O2O买药？\n\n- **事实：** 上海、广东、浙江等地已出现线上医保购药或互联网医保结算样本。\n- **分析：** O2O买药最关键的是医保支付入口、药店结算系统、配送数据和基金监管闭环。\n- **边界：** 城市样本不能直接外推到所有药店。\n\n## 三、对即时零售医药的影响\n\n- **对平台：** 筛选药店时要看医保定点、线上支付、处方审方和基金合规，不只看门店数量。\n- **对药店：** 医保能力越强，越适合承接慢病、处方和复购场景。\n- **对药企：** 进入医保和慢病场景的药品，更需要匹配能承接医保结算和处方留痕的药店。\n\n## 四、使用边界\n\n- 本文是医保能力对比框架，不是药店排名。\n- 任何药店是否具备线上医保、门诊统筹或慢特病承接，均需回到城市政策和门店级资质核验。\n- 平台页面上的“医保”标识只能作为线索，不能替代医保部门或药店定点信息。\n\n## 五、公开来源\n\n{source_list(['fund','retail','beijing','shanghai','guangdong','zhejiang'])}\n''')

# 4 风险案例
write('02-连锁药店/补充资料/连锁药店合规处罚与监管风险案例.md', header('连锁药店合规处罚与监管风险案例', '✅可供研判参考') + f'''## 一句话定位\n\n本文回答：连锁药店合规处罚和监管风险主要集中在哪些类型。核心判断是：连锁药店风险案例应重点看**医保基金、处方药销售、药品质量追溯、价格促销、药师服务和配送售后**六类风险；这些风险决定平台合作时需要做门店级风控，而不是只看连锁品牌。\n\n## 一、事实底座：风险案例类型表\n\n| 风险类型 | 常见触发点 | 政策依据 | 平台合作影响 | 不能证明什么 |\n|---|---|---|---|---|\n| 医保基金风险 | 串换药品、虚假购药、超范围支付、冒名购药 | 医保基金监管条例 | 影响医保专区、门诊统筹和慢病复购 | 单个案例不能代表全部门店 |\n| 处方药风险 | 先药后方、处方来源不清、审方不足 | 药品网络销售办法 | 影响处方药线上承接 | 不能由线上售药入口证明审方合规 |\n| 药品质量风险 | 购销记录不全、储存不当、追溯不完整 | GSP、追溯政策 | 影响履约、售后和召回 | 不能由配送速度证明质量合规 |\n| 价格促销风险 | 低价补贴、误导宣传、赠药促销 | 反不正当竞争、广告规则 | 影响平台活动和流量投放 | 不能由低价证明长期竞争力 |\n| 药师服务风险 | 药师不在岗、咨询不足、审方留痕不足 | 药品网络销售办法 | 影响处方和慢病服务 | 不能由门店数证明服务质量 |\n| 配送售后风险 | 配送异常、包装温控、投诉处理不足 | 药品网络销售办法、追溯政策 | 影响用户体验和合规责任 | 不能由及时送达证明售后闭环 |\n\n## 二、核心问题拆解\n\n### 1. 为什么连锁品牌不能替代门店级合规？\n\n- **事实：** 医保、药品经营和网络销售监管均要求具体机构、具体交易和具体记录可核验。\n- **分析：** 连锁总部能力强，不代表每家门店在医保、处方、库存和履约上都达标。\n- **边界：** 单个风险案例也不能反向证明整个连锁品牌不可合作。\n\n### 2. 平台合作最应防哪些风险？\n\n- **事实：** 平台买药会把流量、医保支付、处方、履约和售后集中到同一链路。\n- **分析：** 风险最高的是基金支付、处方审核和药品质量，因为这些问题会直接影响监管责任。\n- **边界：** 风险表只是风控清单，不是处罚事实清单。\n\n## 三、对即时零售医药的影响\n\n- **对平台：** 入驻审核要从营业资质扩展到医保、处方、药师、追溯和投诉记录。\n- **对药店：** 线上订单增加会放大门店库存、审方、配送和售后的管理压力。\n- **对药企：** 选择O2O渠道时要看药店合规记录，尤其是处方、追溯和召回配合能力。\n\n## 四、使用边界\n\n- 本文是风险类型框架，不列具体处罚名单。\n- 具体处罚事实必须回到监管部门行政处罚决定书、医保曝光台或公司公告。\n- 风险类型用于合作尽调，不能直接作为某家公司存在违规的结论。\n\n## 五、公开来源\n\n{source_list(['fund','retail','netsale','trace','anti'])}\n''')

